// PlugAI project — ESP32-C3-DevKitM-1 (ESP-IDF v5.5)
// Heartbeat LED: green LED (led1) on GPIO4 through 220R (r1) to GND.
// Pattern per 1200 ms cycle: ON 120 ms -> OFF 150 ms -> ON 120 ms -> OFF 810 ms.
// Pure GPIO on/off switching (no LEDC / PWM / RMT / timers).
#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"
#include "esp_log.h"

#define HEARTBEAT_GPIO   GPIO_NUM_4

#define BEAT_ON_MS       120   /* first pulse: LED on            */
#define BEAT_GAP_MS      150   /* pause between the two pulses   */
#define BEAT_ON2_MS      120   /* second pulse: LED on           */
#define BEAT_REST_MS     810   /* long rest (total = 1200 ms)    */

void app_main(void)
{
    printf("PlugAI: heartbeat LED on GPIO4, period 1200 ms "
           "(on 120 / off 150 / on 120 / off 810)\n");

    gpio_config_t io = {
        .pin_bit_mask = (1ULL << HEARTBEAT_GPIO),
        .mode         = GPIO_MODE_OUTPUT,
        .pull_up_en   = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type    = GPIO_INTR_DISABLE,
    };
    ESP_ERROR_CHECK(gpio_config(&io));

    /* Start in the off state so the first visible edge is a rising edge. */
    gpio_set_level(HEARTBEAT_GPIO, 0);

    while (1) {
        gpio_set_level(HEARTBEAT_GPIO, 1);
        vTaskDelay(pdMS_TO_TICKS(BEAT_ON_MS));

        gpio_set_level(HEARTBEAT_GPIO, 0);
        vTaskDelay(pdMS_TO_TICKS(BEAT_GAP_MS));

        gpio_set_level(HEARTBEAT_GPIO, 1);
        vTaskDelay(pdMS_TO_TICKS(BEAT_ON2_MS));

        gpio_set_level(HEARTBEAT_GPIO, 0);
        vTaskDelay(pdMS_TO_TICKS(BEAT_REST_MS));
    }
}
